export const findById = findByAttr("id");
export const findByAriaLabel = findByAttr("aria-label");

const findByTagAndAttr = (attr: string) => (component: ReactWrapper, value: string, tag: string) =>
    component.find(`${tag}[${attr}="${value}"]`);

